using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;using Unity.Collections;using UnityEngine.Rendering;
public static class RebirthCamperWheelBundleCompare{
const string Before="E:/_Haven/shared/REBIRTHBackups/PickupRearCornerClosure_20261021/rebirth_camper80s.unity3d",After="E:/_Haven/shared/REBIRTHStaged/CamperCorrections_20261021/CombinedCandidate/Bundle/rebirth_camper80s.unity3d",Output="E:/_Haven/shared/REBIRTHStaged/CamperCorrections_20261021/CombinedCandidate";
class Data{public Vector3[] V,N;public Vector2[] UV;public int[] T;public string Materials;}
static string PathOf(Transform t,Transform root){string p=t.name;while(t.parent&&t.parent!=root){t=t.parent;p=t.name+"/"+p;}return p;}
static Data ReadMesh(Mesh mesh,Renderer renderer){using(var array=MeshUtility.AcquireReadOnlyMeshData(mesh)){var data=array[0];var v=new NativeArray<Vector3>(data.vertexCount,Allocator.Temp);var n=new NativeArray<Vector3>(data.HasVertexAttribute(VertexAttribute.Normal)?data.vertexCount:0,Allocator.Temp);var uv=new NativeArray<Vector2>(data.HasVertexAttribute(VertexAttribute.TexCoord0)?data.vertexCount:0,Allocator.Temp);try{data.GetVertices(v);if(n.Length>0)data.GetNormals(n);if(uv.Length>0)data.GetUVs(0,uv);var indices=new List<int>();if(data.indexFormat==IndexFormat.UInt16){var raw=data.GetIndexData<ushort>();for(int sub=0;sub<data.subMeshCount;sub++){var desc=data.GetSubMesh(sub);for(int k=0;k<desc.indexCount;k++)indices.Add(raw[desc.indexStart+k]+desc.baseVertex);}}else{var raw=data.GetIndexData<uint>();for(int sub=0;sub<data.subMeshCount;sub++){var desc=data.GetSubMesh(sub);for(int k=0;k<desc.indexCount;k++)indices.Add((int)raw[desc.indexStart+k]+desc.baseVertex);}}if(v.Length==0||indices.Count==0)throw new Exception("Vacuous native wheel data "+mesh.name);return new Data{V=v.ToArray(),N=n.ToArray(),UV=uv.ToArray(),T=indices.ToArray(),Materials=string.Join(";",renderer.sharedMaterials.Select(x=>x.name+":"+x.shader.name+":"+x.color+":"+(x.mainTexture?x.mainTexture.name:"null")))};}finally{v.Dispose();n.Dispose();uv.Dispose();}}}
static Dictionary<string,Data> Read(string path){var bundle=AssetBundle.LoadFromFile(path);if(!bundle)throw new Exception(path);try{var root=bundle.LoadAsset<GameObject>("rebirthCamper80s");return root.GetComponentsInChildren<MeshFilter>(true).Where(f=>PathOf(f.transform,root.transform).Contains("wheel_",StringComparison.OrdinalIgnoreCase)).ToDictionary(f=>PathOf(f.transform,root.transform),f=>ReadMesh(f.sharedMesh,f.GetComponent<Renderer>()));}finally{bundle.Unload(true);}}
static string Vertex(Vector3 p)=>p.x.ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+","+p.y.ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+","+p.z.ToString("F6",System.Globalization.CultureInfo.InvariantCulture);
static string Key(Data d,int tri){var keys=new[]{Vertex(d.V[d.T[tri]]),Vertex(d.V[d.T[tri+1]]),Vertex(d.V[d.T[tri+2]])};var c=new[]{keys[0]+"|"+keys[1]+"|"+keys[2],keys[1]+"|"+keys[2]+"|"+keys[0],keys[2]+"|"+keys[0]+"|"+keys[1]};Array.Sort(c,StringComparer.Ordinal);return c[0];}
public static void Run(){var before=Read(Before);var after=Read(After);if(before.Count<4||before.Count!=after.Count)throw new Exception("Wheel render mesh count changed");var log=new StringBuilder("Original installed bundle vs staged candidate; Editor MeshUtility.AcquireReadOnlyMeshData reads actual nonreadable vertex/index buffers; zero vertices/triangles forbidden; geometric triangle matching at1e-6metres, cyclic ordering preserves winding; numeric position/UV/normal errors measured.\n");foreach(var pair in before){var a=pair.Value;if(!after.TryGetValue(pair.Key,out var b))throw new Exception("Missing wheel "+pair.Key);if(a.T.Length!=b.T.Length||a.Materials!=b.Materials)throw new Exception("Wheel triangle/material changed "+pair.Key);var lookup=new Dictionary<string,Queue<int>>();for(int i=0;i<a.T.Length;i+=3){var key=Key(a,i);if(!lookup.TryGetValue(key,out var q))lookup[key]=q=new Queue<int>();q.Enqueue(i);}float pos=0,uv=0,normal=0;for(int i=0;i<b.T.Length;i+=3){var key=Key(b,i);if(!lookup.TryGetValue(key,out var q)||q.Count==0)throw new Exception("Wheel triangle position/winding differs beyond1e-6 "+pair.Key);int j=q.Dequeue();int shift=-1;for(int c=0;c<3;c++)if((a.V[a.T[j+c]]-b.V[b.T[i]]).sqrMagnitude<=1e-12){shift=c;break;}if(shift<0)throw new Exception("Wheel corner matching");for(int c=0;c<3;c++){int ia=a.T[j+(shift+c)%3],ib=b.T[i+c];pos=Mathf.Max(pos,Vector3.Distance(a.V[ia],b.V[ib]));if(a.UV.Length!=b.UV.Length)throw new Exception("Wheel UV missing");if(a.UV.Length>0)uv=Mathf.Max(uv,Vector2.Distance(a.UV[ia],b.UV[ib]));if(a.N.Length!=b.N.Length)throw new Exception("Wheel normals missing");if(a.N.Length>0)normal=Mathf.Max(normal,a.N[ia].Equals(b.N[ib])?0:Vector3.Angle(a.N[ia],b.N[ib]));}}if(lookup.Values.Any(q=>q.Count!=0)||pos>1e-6||uv>1e-6||normal>.001)throw new Exception("Wheel numeric preservation failed "+pair.Key+" pos="+pos+" uv="+uv+" normal="+normal);log.AppendLine("PASS "+pair.Key+" triangles="+a.T.Length/3+" vertsBefore="+a.V.Length+" after="+b.V.Length+" normalsBefore="+a.N.Length+" after="+b.N.Length+" maxPositionMetres="+pos.ToString("R")+" maxUV="+uv.ToString("R")+" maxNormalAngleDegrees="+normal.ToString("R")+" materialsIdentical=true");}Directory.CreateDirectory(Output);File.WriteAllText(Output+"/wheel-bundle-numeric-receipt.txt",log.ToString());Debug.Log("WHEEL_BUNDLE_NUMERIC_COMPARE_PASS "+before.Count);}}
